    FragmentSelectorType.add_member(:producer_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PRODUCER_TIMESTAMP', traits: {"smithy.api#enumValue" => "PRODUCER_TIMESTAMP"}))
    FragmentSelectorType.add_member(:server_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SERVER_TIMESTAMP', traits: {"smithy.api#enumValue" => "SERVER_TIMESTAMP"}))
    GetClipInput.add_member(:stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: StreamName, location_name: 'StreamName', traits: {"smithy.api#documentation" => "<p>The name of the stream for which to retrieve the media clip. </p>\n         <p>You must specify either the StreamName or the StreamARN. </p>"}))
    GetClipInput.add_member(:stream_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceARN, location_name: 'StreamARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the stream for which to retrieve the media clip. </p>\n         <p>You must specify either the StreamName or the StreamARN. </p>"}))
    GetClipInput.add_member(:clip_fragment_selector, Smithy::Schema::Shapes::ShapeRef.new(shape: ClipFragmentSelector, location_name: 'ClipFragmentSelector', traits: {"smithy.api#documentation" => "<p>The time range of the requested clip and the source of the timestamps.</p>", "smithy.api#required" => {}}))
    GetClipInput.type = Types::GetClipInput
    GetClipOutput.add_member(:content_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ContentType, location_name: 'ContentType', traits: {"smithy.api#documentation" => "<p>The content type of the media in the requested clip.</p>", "smithy.api#httpHeader" => "Content-Type"}))
    GetClipOutput.add_member(:payload, Smithy::Schema::Shapes::ShapeRef.new(shape: Payload, location_name: 'Payload', traits: {"smithy.api#default" => "", "smithy.api#documentation" => "<p>Traditional MP4 file that contains the media clip from the specified video stream. The\n            output will contain the first 100 MB or the first 200 fragments from the specified start\n            timestamp. For more information, see <a href=\"https://docs.aws.amazon.com/kinesisvideostreams/latest/dg/limits.html\">Kinesis\n                Video Streams Limits</a>. </p>", "smithy.api#httpPayload" => {}}))
    GetClipOutput[:http_payload] = :payload
